import { t, type Lang } from "./i18n";

/** Data shown in the About dialog. */
export interface AboutInfo {
  version: string;
  lang: Lang;
  repoUrl: string;
  logoSrc: string;
  /** Components and licences (generated by scripts/third-party.mjs). */
  components?: Component[];
}

export interface Component {
  name: string;
  version: string;
  license: string;
  url: string;
  kind: string;
  ru: string;
  en: string;
}

/** Only web links are made clickable. */
function safeUrl(url: string): string {
  return /^https:\/\//.test(url) ? url : "";
}

function renderComponents(lang: Lang, items: Component[]): string {
  const rows = items
    .map((c) => {
      const url = safeUrl(c.url);
      const name = url
        ? `<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(c.name)}</a>`
        : escapeHtml(c.name);
      return `<tr><td>${name}</td><td>${escapeHtml(c.version)}</td><td>${escapeHtml(c.license)}</td><td>${escapeHtml(lang === "ru" ? c.ru : c.en)}</td></tr>`;
    })
    .join("");
  return `<details class="about-components"><summary>${escapeHtml(t(lang, "components"))}</summary>
    <table><thead><tr><th>${escapeHtml(t(lang, "componentName"))}</th><th>${escapeHtml(t(lang, "version"))}</th><th>${escapeHtml(t(lang, "license"))}</th><th>${escapeHtml(t(lang, "componentPurpose"))}</th></tr></thead><tbody>${rows}</tbody></table></details>`;
}

/** Escape text for safe use inside HTML. */
export function escapeHtml(text: string): string {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

/** Inner HTML of the About dialog. */
export function renderAbout(info: AboutInfo): string {
  const { lang } = info;
  return `
    <img class="about-logo" src="${escapeHtml(info.logoSrc)}" alt="Allods Data Viewer" width="220" height="220" />
    <h2 id="about-title">${escapeHtml(t(lang, "aboutTitle"))}</h2>
    <p>${escapeHtml(t(lang, "tagline"))}</p>
    <dl class="about-facts">
      <dt>${escapeHtml(t(lang, "version"))}</dt><dd>${escapeHtml(info.version)}</dd>
      <dt>${escapeHtml(t(lang, "license"))}</dt><dd>${escapeHtml(t(lang, "licenseValue"))}</dd>
      <dt>${escapeHtml(t(lang, "source"))}</dt><dd><a href="${escapeHtml(info.repoUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(info.repoUrl)}</a></dd>
    </dl>
    ${info.components?.length ? renderComponents(lang, info.components) : ""}
    <p class="about-note">${escapeHtml(t(lang, "legal"))}</p>
    <form method="dialog"><button class="btn">${escapeHtml(t(lang, "close"))}</button></form>
  `;
}
